local PsalteryMaker = {}
local PRODUCTS = {
    triangle_psaltery = { name = "Trikotni psalterij", woodCost = 2, gutCost = 3, time = 2, cost = 35, soundQuality = 8, prestige = 1, description = "Trikotni psalterij z 12 strunami." },
    square_psaltery = { name = "Kvadratni psalterij", woodCost = 3, gutCost = 5, time = 4, cost = 110, soundQuality = 12, prestige = 3, description = "Kvadratni psalterij za samostane." },
    bowed_psaltery = { name = "Lokani psalterij", woodCost = 3, gutCost = 6, time = 6, cost = 260, soundQuality = 16, prestige = 6, happiness = 1, description = "Lokani psalterij z zvokom kot harfa." },
    double_psaltery = { name = "Dvojni psalterij", woodCost = 4, gutCost = 10, time = 8, cost = 580, soundQuality = 20, prestige = 11, happiness = 2, description = "Dvojni psalterij z basovimi in diskantnimi strunami." },
    silver_psaltery = { name = "Srebrni psalterij", woodCost = 4, silverCost = 1, gutCost = 8, time = 11, cost = 1100, soundQuality = 26, prestige = 18, happiness = 4, description = "Srebrni psalterij za slovesne dvorne koncerte." },
    royal_hammered_psaltery = { name = "Kraljevski kladivčasti psalterij", woodCost = 6, goldCost = 2, silverCost = 1, gutCost = 14, pearlCost = 1, time = 15, cost = 2400, soundQuality = 38, prestige = 50, happiness = 10, description = "Veliki kraljevski kladivčasti psalterij z zlatim in bisernim okovjem." },
}
local BUILDINGS = {
    workshop = { name = "Psalterijska delavnica", cost = { gold = 260, wood = 130 }, upkeep = 6, qualityBonus = 5 },
    stringing_room = { name = "Strunarska soba", cost = { gold = 800, wood = 220, stone = 200, gut = 8 }, upkeep = 20, qualityBonus = 18 },
    tuning_room = { name = "Naglasilnica", cost = { gold = 1700, wood = 280, stone = 350, silver = 25, wood2 = 8 }, upkeep = 40, qualityBonus = 30 },
    royal_psaltery_atelier = { name = "Kraljevski atelje psalterijev", cost = { gold = 6500, wood = 500, stone = 700, gold = 50, silver = 30 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
PsalteryMaker.woodStock = 16; PsalteryMaker.gutStock = 14; PsalteryMaker.silverStock = 6; PsalteryMaker.goldStock = 6; PsalteryMaker.pearlStock = 4
PsalteryMaker.productStock = {}; PsalteryMaker.buildings = {}; PsalteryMaker.maker = nil; PsalteryMaker.activeMaking = {}; PsalteryMaker.totalProducts = 0; PsalteryMaker.dayTimer = 0
function PsalteryMaker.init() PsalteryMaker.woodStock=16; PsalteryMaker.gutStock=14; PsalteryMaker.silverStock=6; PsalteryMaker.goldStock=6; PsalteryMaker.pearlStock=4; PsalteryMaker.productStock={}; PsalteryMaker.buildings={}; PsalteryMaker.maker=nil; PsalteryMaker.activeMaking={}; PsalteryMaker.totalProducts=0; PsalteryMaker.dayTimer=0; print("[PsalteryMaker] Royal Psaltery Maker System initialized (6 products, 4 buildings)") end
function PsalteryMaker.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PsalteryMaker.maker={name=n or ("Psalterjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Psalterjar najet: %s (spretnost: %d)",PsalteryMaker.maker.name,s),"success") end; return true end
function PsalteryMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PsalteryMaker.build(id) local ok,e=PsalteryMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PsalteryMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PsalteryMaker.getQualityBonus() local b=0; for _,bd in ipairs(PsalteryMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PsalteryMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and PsalteryMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.gutCost and PsalteryMaker.gutStock<(d.gutCost or 0) then return false,"Premalo črevesja" end; if d.silverCost and PsalteryMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PsalteryMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.pearlCost and PsalteryMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PsalteryMaker.buildings==0 then return false,"Potrebna delavnica" end; if not PsalteryMaker.maker then return false,"Potreben psalterjar" end; return true end
function PsalteryMaker.make(pt,qty) qty=qty or 1; local ok,e=PsalteryMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then PsalteryMaker.woodStock=PsalteryMaker.woodStock-d.woodCost*qty end; if d.gutCost then PsalteryMaker.gutStock=PsalteryMaker.gutStock-d.gutCost*qty end; if d.silverCost then PsalteryMaker.silverStock=PsalteryMaker.silverStock-d.silverCost*qty end; if d.goldCost then PsalteryMaker.goldStock=PsalteryMaker.goldStock-d.goldCost*qty end; if d.pearlCost then PsalteryMaker.pearlStock=PsalteryMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PsalteryMaker.maker then t=math.max(1,t-math.floor(PsalteryMaker.maker.skill/12)) end; table.insert(PsalteryMaker.activeMaking,{id="psaltery_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,soundQuality=d.soundQuality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PsalteryMaker.completeMaking(m) local q=1.0+(PsalteryMaker.getQualityBonus()/100); if PsalteryMaker.maker then q=q+(PsalteryMaker.maker.skill/180) end; q=math.min(2.0,q); PsalteryMaker.productStock[m.productType]=(PsalteryMaker.productStock[m.productType] or 0)+m.quantity; PsalteryMaker.totalProducts=PsalteryMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PsalteryMaker.maker then PsalteryMaker.maker.itemsMade=PsalteryMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then PsalteryMaker.maker.skill=math.min(100,PsalteryMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Psalterij izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"psaltery.completed",{productName=m.productName,soundQuality=m.soundQuality}) end end
function PsalteryMaker.update(dt) if not _G.state then return end; PsalteryMaker.dayTimer=PsalteryMaker.dayTimer+dt; if PsalteryMaker.dayTimer>=30 then PsalteryMaker.dayTimer=0; for i=#PsalteryMaker.activeMaking,1,-1 do local m=PsalteryMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PsalteryMaker.completeMaking(m); table.remove(PsalteryMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PsalteryMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PsalteryMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PsalteryMaker.getStats() return {woodStock=PsalteryMaker.woodStock,gutStock=PsalteryMaker.gutStock,silverStock=PsalteryMaker.silverStock,goldStock=PsalteryMaker.goldStock,pearlStock=PsalteryMaker.pearlStock,productStock=PsalteryMaker.productStock,numBuildings=#PsalteryMaker.buildings,hasMaker=PsalteryMaker.maker~=nil,makerName=PsalteryMaker.maker and PsalteryMaker.maker.name or "—",makerSkill=PsalteryMaker.maker and PsalteryMaker.maker.skill or 0,activeMaking=#PsalteryMaker.activeMaking,totalProducts=PsalteryMaker.totalProducts} end
return PsalteryMaker
